-- TEST DATA ONLY. Generated by supabase/demo/gen_demo_sites.mjs; do not edit by hand.
-- Re-seeds the demo sites (shatrughan-sinha) with the website-v2 starter content and links
-- their agents to the demo company 'demo-life' (approved). Run as postgres in the SQL Editor AFTER
-- 20261017132241_companies_offers.sql, 20261018073025_catalog_sync.sql and supabase/demo/demo_offers.sql.
-- Idempotent. Keeps each site's contact section, hero photo and designation (they never leave the database).
begin;

-- No company link (--no-link): a "Meet me" site shows no offers.

-- shatrughan-sinha: classic (personal), en
update public.sites s
   set template_key = 'classic',
       accent = 'indigo',
       locale = 'en',
       draft_content = v.content,
       published_content = v.content,
       published_at = now()
  from (select s2.id,
               '{"hero":{"headline":"Hello, I''m Shatrughan Sinha","subheadline":"Planning your family''s future? Let''s find cover that fits your needs and budget. I''m with you from the first question to the claim."},"about":{"bio":"Hello, I''m Shatrughan Sinha, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]},"services":{"offered":["term","endowment","child","pension","health"],"items":[{"interest":"term","description":"High cover at a low premium, so your family stays financially secure if something happens to you."},{"interest":"endowment","description":"Protection and regular saving in one plan, with a benefit at maturity as per the policy terms."},{"interest":"child","description":"Plan ahead for your child''s education and milestones, with cover that keeps the plan going even if you''re not there."},{"interest":"pension","description":"Build a regular income for retirement, so you stay independent and comfortable in your later years."},{"interest":"health","description":"Cover for hospital bills and medical emergencies for you and your family, so your savings stay safe."}]},"highlights":{"items":[{"icon":"support_agent","title":"Personal guidance","text":"Advice shaped around your family, your goals and your budget."},{"icon":"schedule","title":"Timely reminders","text":"Renewals and due dates tracked for you, so nothing slips through."},{"icon":"handshake","title":"Honest advice","text":"No pressure and no jargon, just clear answers you can trust."},{"icon":"verified_user","title":"Help with claims","text":"If you ever need to claim, I''ll guide your family through every step."}]},"faq":{"items":[{"question":"How much life cover do I need?","answer":"There''s no single number. I look at what your family would need to keep going, such as daily expenses, loans and children''s studies, and at what you already have. Then we choose cover that fits your budget."},{"question":"What is the difference between term insurance and a savings plan?","answer":"Think of term insurance as pure protection: the highest cover for the lowest premium, with no payout if you outlive the term. Savings plans add a maturity benefit, which means a higher premium. Many families combine the two. Let''s see what suits you."},{"question":"Which documents do I need to buy a policy?","answer":"The basics are simple: identity proof, address proof, a photo and bank details. Depending on the plan and the cover amount, income proof or a health check-up may also be asked for. I''ll tell you exactly what''s needed before we start."},{"question":"How can I pay my premium?","answer":"Yearly, half-yearly, quarterly or monthly: pick what fits your budget. You can pay online, set up auto-debit or pay at a branch. I keep track of your due dates and remind you in time. Any tax benefit applies as per prevailing tax laws."},{"question":"Will you help with claims?","answer":"Absolutely. Helping with claims is part of my service. Just call me, and together we''ll prepare the paperwork and keep track of it until the claim is decided."}]},"sectionOrder":["hero","about","services","offers","highlights","achievements","testimonials","faq","contact"],"hidden":["achievements","testimonials","offers"]}'::jsonb
               || jsonb_build_object('contact', coalesce(s2.published_content -> 'contact', s2.draft_content -> 'contact', '{}'::jsonb))
               || jsonb_build_object('hero', ('{"headline":"Hello, I''m Shatrughan Sinha","subheadline":"Planning your family''s future? Let''s find cover that fits your needs and budget. I''m with you from the first question to the claim."}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('photo', s2.published_content #> '{hero,photo}')))
               || jsonb_build_object('about', ('{"bio":"Hello, I''m Shatrughan Sinha, and my work is helping families feel secure about tomorrow. Whether you''re buying your first policy, planning your child''s education or thinking about retirement, I''ll explain your choices clearly and help you decide with confidence. No jargon, no pressure, just honest guidance.","languagesSpoken":["english"]}'::jsonb)
                    || jsonb_strip_nulls(jsonb_build_object('designation', s2.published_content #> '{about,designation}')))
               as content
          from public.sites s2
         where s2.slug = 'shatrughan-sinha' and s2.deleted_at is null) v
 where s.id = v.id;

commit;

-- Check (public data only): both sites render with offers and no company name.
select s.slug, s.template_key,
       jsonb_array_length(coalesce(public.get_public_site(s.slug) #> '{offers,items}', '[]'::jsonb)) as offers,
       public.get_public_site(s.slug) -> 'company' as company
  from public.sites s where s.slug in ('shatrughan-sinha');
